```python
import json
import re
from dataclasses import dataclass

MAX_BODY_BYTES = 8 * 1024
ITEM_ID = re.compile(r"[A-Za-z0-9_-]{1,64}")


class InvalidRequest(ValueError):
    pass


class BodyTooLarge(InvalidRequest):
    pass


@dataclass(frozen=True)
class ItemRequest:
    item_id: str
    quantity: int


def reject_constant(value):
    # json.loads otherwise accepts non-JSON NaN/Infinity tokens.
    raise InvalidRequest("Non-finite numbers are not allowed")


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise InvalidRequest("Duplicate object field")
        result[key] = value
    return result


def validate_body(raw: bytes) -> ItemRequest:
    if len(raw) > MAX_BODY_BYTES:
        raise BodyTooLarge("Request body is too large")

    try:
        value = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=unique_object,
            parse_constant=reject_constant,
        )
    except InvalidRequest:
        raise
    except (UnicodeDecodeError, ValueError, RecursionError) as exc:
        raise InvalidRequest("Malformed JSON body") from exc

    if not isinstance(value, dict):
        raise InvalidRequest("Expected a JSON object")
    if set(value) != {"item_id", "quantity"}:
        raise InvalidRequest("Expected item_id and quantity only")

    item_id = value["item_id"]
    quantity = value["quantity"]
    if not isinstance(item_id, str) or ITEM_ID.fullmatch(item_id) is None:
        raise InvalidRequest("Invalid item_id")
    # bool is a subclass of int in Python, so isinstance alone is insufficient.
    if type(quantity) is not int or not 1 <= quantity <= 100:
        raise InvalidRequest("quantity must be an integer from 1 to 100")

    return ItemRequest(item_id=item_id, quantity=quantity)
```

